package br.com.gabaritei.piloto

import org.json.JSONObject
import org.json.JSONArray
import org.junit.Assert.*
import org.junit.Test

class PlanEditsTest {
    private fun state():JSONObject=StateCompat.empty().put("planos",JSONArray().put(JSONObject().put("id","p").put("plano",JSONObject().put("concurso","Plano")).put("disciplinas",JSONArray().put(JSONObject().put("id","d").put("nome","Direito").put("campoFuturo",99).put("topicos",JSONArray().put(JSONObject().put("id","t").put("nome","Tema").put("status","pendente"))))))).put("sessoes",JSONArray().put(JSONObject().put("id","old").put("planoId","p").put("topicoId","t").put("data","2026-10-20").put("duracaoMin",20).put("qFeitas",10).put("qCertas",8)))
    private fun edit(s:JSONObject,p:JSONObject):JSONObject{PlanEdits.apply(s,p.put("planId","p"),"2026-10-29T12:00:00Z",false);return s}
    private fun d(s:JSONObject)=s.getJSONArray("planos").getJSONObject(0).getJSONArray("disciplinas").getJSONObject(0)
    @Test fun renameKeepsIdsHistoryAndUnknownFields(){val s=edit(state(),JSONObject().put("action","discipline").put("disciplineId","d").put("beforeName","Direito").put("name","Direito Administrativo"));assertEquals("d",d(s).getString("id"));assertEquals(99,d(s).getInt("campoFuturo"));assertEquals("t",s.getJSONArray("sessoes").getJSONObject(0).getString("topicoId"));assertEquals(1,d(s).getJSONObject("camposAtualizados").getJSONObject("nome").getInt("rev"))}
    @Test fun archiveAndRestorePreserveHistory(){val s=state();edit(s,JSONObject().put("action","discipline").put("disciplineId","d").put("archived",true));assertEquals("paused",d(s).getString("planejamentoStatus"));assertEquals(1,s.getJSONArray("sessoes").length());edit(s,JSONObject().put("action","discipline").put("disciplineId","d").put("archived",false));assertFalse(d(s).getBoolean("androidArquivada"))}
    @Test fun topicCanBeRestoredAfterLastTopicWasArchived(){val s=state();edit(s,JSONObject().put("action","topic").put("disciplineId","d").put("topicId","t").put("archived",true));assertEquals(1,StateCompat.plans(s.toString(),emptyList()).size);assertEquals(1,StateCompat.plans(s.toString(),emptyList()).first().disciplines.size);edit(s,JSONObject().put("action","topic").put("disciplineId","d").put("topicId","t").put("archived",false));assertEquals(1,StateCompat.plans(s.toString(),emptyList()).first().topics.size)}
    @Test fun reorderingIsIdempotentAndKeepsNewConcurrentRows(){val s=state();edit(s,JSONObject().put("action","add-discipline").put("disciplineId","new").put("newTopicId","nt").put("name","Português"));val op=JSONObject().put("action","order").put("ids",JSONArray(listOf("new","d")));edit(s,op);edit(s,op);assertEquals("new",d(s).getString("id"));assertEquals(2,s.getJSONArray("planos").getJSONObject(0).getJSONArray("disciplinas").length())}
    @Test fun cycleTimeKeepsCreditsAndRound(){val s=state();s.getJSONArray("planos").getJSONObject(0).getJSONObject("plano").put("ciclo",JSONObject().put("volta",3).put("blocos",JSONArray().put(JSONObject().put("id","b").put("disciplinaId","d").put("feitoMin",20).put("metaMin",50).put("creditosCiclo",JSONObject().put("evento",20)))))
        edit(s,JSONObject().put("action","cycle-block").put("blockId","b").put("minutes",60));val cycle=s.getJSONArray("planos").getJSONObject(0).getJSONObject("plano").getJSONObject("ciclo");assertEquals(3,cycle.getInt("volta"));val b=cycle.getJSONArray("blocos").getJSONObject(0);assertEquals(20,b.getInt("feitoMin"));assertEquals(60,b.getInt("metaMin"));assertEquals(20,b.getJSONObject("creditosCiclo").getInt("evento"))
    }
    @Test fun archivedTopicKeepsDisciplineStatistics(){val s=state();edit(s,JSONObject().put("action","topic").put("disciplineId","d").put("topicId","t").put("archived",true));val rows=StudyMetrics.activities(StateCompat.plans(s.toString(),emptyList()).first(),StateCompat.sessions(s.toString()),s.toString());assertEquals("d",rows.single().discipline);assertEquals(10,rows.single().questions)}
    @Test fun concurrentRenameIsReported(){val s=state();assertThrows(SyncConflict::class.java){edit(s,JSONObject().put("action","discipline").put("disciplineId","d").put("beforeName","Nome antigo").put("name","Novo"))}}
    @Test fun freeStudyDoesNotChangeThePlanOrAgenda(){val s=state();val row=JSONObject().put("id","free").put("data","2026-10-29").put("duracaoMin",30).put("qFeitas",5).put("qCertas",4).put("topicoNome","Leitura livre").put("tipo","teoria");val op=PendingMutation("op","free-session",JSONObject().put("session",row).toString(),"",1793280000000)
        val once=StateCompat.apply(s.toString(),listOf(op));val twice=StateCompat.apply(once,listOf(op));val parsed=StateCompat.sessions(twice);assertEquals(2,parsed.size);val free=StudyMetrics.freeActivities(parsed,twice);assertEquals(1,free.size);assertEquals("Leitura livre",free.single().title);assertEquals(0,JSONObject(twice).getJSONArray("agenda").length());System.getenv("GABARITEI_EDITS_FIXTURE_OUT")?.let{java.io.File(it).writeText(twice)};assertEquals(20.0,StudyMetrics.activities(StateCompat.plans(twice,emptyList()).first(),parsed,twice).sumOf{it.minutes},0.01)
    }
}
